package mcp

// The tools/list entries of the event subscription tools, as src/mcp.ts's JSON.stringify writes them (generated by testdata/genlistings.mjs; mcp_test.go compares).
var eventsListings = map[string]string{
	"subscribe":          "{\"name\":\"subscribe\",\"description\":\"Ask to be told about external events (GitHub, Linear, Slack, and other sources): each matching event arrives as a notice while you work, or as mail from stam when you are idle. Filter by source, subjects (glob patterns over keys like `github:OWNER/REPO#12`, `github:OWNER/*`, `linear:TEAM-123`, `slack:CHANNEL`), types (glob patterns like `pull_request.*`), actors, and exclude_actors. By default you subscribe yourself; pass `itsa` to notify an ITSA's thread instead, or `for` another agent in your tree (an ITSA you take part in, or the human, if allowed). Events close in time arrive as one message. Returns a subscription id for unsubscribe.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"source\":{\"type\":\"string\",\"description\":\"Only this source, for example github.\"},\"subjects\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Subject glob patterns; * matches within one segment.\"},\"types\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Event type glob patterns, for example pull_request.*.\"},\"actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Only events by these actors.\"},\"exclude_actors\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"description\":\"Skip events by these actors.\"},\"itsa\":{\"type\":\"string\",\"description\":\"Subscribe an ITSA (id or key): matching events post into its thread instead.\"},\"for\":{\"type\":\"string\",\"description\":\"Subscribe another agent (id or name) in your tree, or \\\"human\\\". Defaults to you.\"},\"note\":{\"type\":\"string\",\"description\":\"A short label carried in the deliveries.\"},\"expires_in_minutes\":{\"type\":\"number\",\"description\":\"Let the subscription expire after this many minutes.\"}}},\"group\":\"events\"}",
	"unsubscribe":        "{\"name\":\"unsubscribe\",\"description\":\"Remove one of your event subscriptions (or one you created) by its id, from subscribe or list_subscriptions.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"},\"id\":{\"type\":\"string\",\"description\":\"The subscription id.\"}},\"required\":[\"id\"]},\"group\":\"events\"}",
	"list_subscriptions": "{\"name\":\"list_subscriptions\",\"description\":\"List event subscriptions you made or that name you as the subscriber: id, subscriber, filter, note, and expiry.\",\"inputSchema\":{\"type\":\"object\",\"properties\":{\"self\":{\"type\":\"string\",\"description\":\"Your stam agent id. Needed only when your system prompt asks for it.\"}}},\"group\":\"events\"}",
}
